function packageCount(value: unknown): number | undefined {
  if (typeof value !== "object" || value === null || !("count" in value)) {
    return undefined;
  }
  const count = value.count;
  if (typeof count === "number" && Number.isInteger(count) && count >= 0) {
    return count;
  }
  return undefined;
}

