function summarize(orders: Order[]): Summary {
  const summary: Summary = { count: orders.length, revenue: 0, pending: 0 };
  for (const order of orders) {
    if (order.status === "paid") {
      summary.revenue += order.total;      // здесь order — Paid
    } else if (order.status === "pending") {
      summary.pending += order.total;      // здесь order — Pending
    }
    // refunded: в денежные итоги не входит
  }
  return summary;
}

type Paid = { id: number; status: "paid"; total: number };
type Pending = { id: number; status: "pending"; total: number };
type Refunded = { id: number; status: "refunded"; total: number };
type Order = Paid | Pending | Refunded;

interface Summary {
  count: number;
  revenue: number;
  pending: number;
}

function summarize(orders: Order[]): Summary {
  const summary: Summary = { count: orders.length, revenue: 0, pending: 0 };
  for (const order of orders) {
    if (order.status === "paid") {
      summary.revenue += order.total;
    } else if (order.status === "pending") {
      summary.pending += order.total;
    }
  }
  return summary;
}

const orders: Order[] = [
  { id: 1, status: "paid", total: 120 },
  { id: 2, status: "pending", total: 80 },
  { id: 3, status: "paid", total: 45 },
  { id: 4, status: "refunded", total: 60 },
];

const report = summarize(orders);
console.log("orders:", report.count);
console.log("revenue:", report.revenue);
console.log("pending:", report.pending);

