type Borrowing =
  | { id: number; status: "active"; dueDay: string }
  | { id: number; status: "returned"; returnedDay: string };

function summarizeBorrowing(entries: Borrowing[]) {
  const totals = { active: 0, returned: 0 };
  for (const entry of entries) {
    totals[entry.status] += 1;
  }
  return totals;
}

const result = summarizeBorrowing([
  { id: 1, status: "active", dueDay: "Monday" },
  { id: 2, status: "returned", returnedDay: "Tuesday" },
]);
console.log("active:", result.active);
console.log("returned:", result.returned);
